//! Narrow engine write for generated export views. Ordinary tools stay protected.
//!
//! The default exports live in the hidden `.wiki-island/exports/` folder.
//! The first publication of a host whose old visible `exports/` file still
//! holds unmodified generated bytes moves that file there, so it is removed
//! exactly once and only when it is what wi wrote.
use crate::error::Result;
use crate::paths::{HOST_EXPORTS, Target, check_no_symlink, is_default_export, normalize};
use crate::publish::{Change, Expect};
use crate::work::{WorkKind, WorkRequest};
use crate::{Ingress, StoreError, Vault, WriteResult};
use wi_history::hash_bytes;

pub const GENERATED_PREFIX: &str = "<!-- wiki-island generated ";
/// Visible folder older versions wrote the exports to.
const LEGACY_EXPORTS_DIR: &str = "exports";

impl Vault {
    /// Verify an existing generated file, retaining any hand edit and opening work.
    pub fn export_checksum(&self, host: &str) -> Result<Option<String>> {
        let (_, existing) = self.export_file(host)?;
        Ok(existing.map(|b| hash_bytes(&b)))
    }
    fn export_file(&self, host: &str) -> Result<(String, Option<Vec<u8>>)> {
        let (_, default, _) = host_export(host)?;
        let key = format!("export_{host}_path");
        let input = self
            .config()
            .get(&key)
            .and_then(|v| v.as_str())
            .unwrap_or(default);
        if std::path::Path::new(input).is_absolute() {
            return Err(StoreError::Invalid(
                "export paths must be vault-relative".into(),
            ));
        }
        let rel = normalize(self.root(), input)?;
        // A configuration mistake must not write engine state or scratch paths.
        // Under `.wiki-island/` only the default export files are allowed.
        let plain = wi_note::VaultConfig::parse("")?;
        match crate::paths::check_protected(&plain, &rel) {
            Err(StoreError::Protected {
                reason: "generated export",
                ..
            })
            | Ok(()) => {}
            Err(_) if is_default_export(&rel) => {}
            Err(e) => return Err(e),
        }
        check_no_symlink(self.root(), &rel)?;
        let existing = crate::contained::read_rel(self.root(), &rel)?;
        if let Some(bytes) = &existing
            && !is_generated(bytes)
        {
            self.record_work(WorkRequest::new(
                WorkKind::RecoveryProblem,
                &rel,
                "generated export was hand edited; preserve it, move it aside, and regenerate",
            ))?;
            self.convert_work_requests()?;
            return Err(StoreError::LifecycleRefused {
                code: "export-hand-edited",
                message: format!("{rel}: hand edits retained; inspect the recheck work item"),
            });
        }
        Ok((rel, existing))
    }
    /// Publish a view only at its configured host path. Existing bytes must
    /// carry a valid digest; a hand edit is retained and opens a work item.
    pub fn publish_export(&self, host: &str, body: &str) -> Result<WriteResult> {
        let (rel, existing) = self.export_file(host)?;
        let legacy = match &existing {
            None if is_default_export(&rel) => self.legacy_export(host)?,
            _ => None,
        };
        let bytes = format!(
            "{GENERATED_PREFIX}{} -->\n{body}",
            hash_bytes(body.as_bytes())
        )
        .into_bytes();
        let digest = hash_bytes(&bytes);
        self.publish(Change {
            target: Target {
                abs: self.root().join(&rel),
                rel,
            },
            bytes,
            expect: existing
                .map(|b| Expect::Hash(hash_bytes(&b)))
                .unwrap_or(Expect::Absent),
            moved_from: legacy,
            op_id: None,
            digest,
            ingress: Ingress::Engine,
            revert_of: None,
            charge: None,
        })
    }

    /// Remove old visible exports that reappeared (synced back from a
    /// device that still had them) while the hidden export exists: one that
    /// is byte-identical to the hidden file is folded into it by a guarded
    /// move, so it never surfaces as a duplicate note. Anything else there
    /// (a hand edit, an older generation, a foreign file) is left alone.
    /// An empty legacy folder is then removed. Returns the files removed.
    pub(crate) fn retire_legacy_exports(&self) -> Result<usize> {
        let mut removed = 0;
        for (host, default, legacy) in HOST_EXPORTS {
            let configured = self
                .config()
                .get(&format!("export_{host}_path"))
                .and_then(|v| v.as_str())
                .map(|p| normalize(self.root(), p))
                .transpose()
                .ok()
                .flatten();
            if configured.is_some_and(|p| !is_default_export(&p)) {
                continue;
            }
            if check_no_symlink(self.root(), legacy).is_err()
                || check_no_symlink(self.root(), default).is_err()
            {
                continue;
            }
            let Some(hidden) = crate::contained::read_rel(self.root(), default)? else {
                continue;
            };
            let Some(old) = crate::contained::read_rel(self.root(), legacy)? else {
                continue;
            };
            if old != hidden || !is_generated(&hidden) {
                continue;
            }
            let hash = hash_bytes(&hidden);
            self.publish(Change {
                target: Target {
                    abs: self.root().join(default),
                    rel: default.to_owned(),
                },
                bytes: hidden,
                expect: Expect::Hash(hash.clone()),
                moved_from: Some((
                    Target {
                        abs: self.root().join(legacy),
                        rel: legacy.to_owned(),
                    },
                    hash.clone(),
                )),
                op_id: None,
                digest: hash,
                ingress: Ingress::Engine,
                revert_of: None,
                charge: None,
            })?;
            removed += 1;
        }
        let folder = self.root().join(LEGACY_EXPORTS_DIR);
        if removed > 0
            && std::fs::symlink_metadata(&folder)
                .is_ok_and(|meta| meta.is_dir() && !meta.file_type().is_symlink())
            && std::fs::remove_dir(&folder).is_ok()
        {
            wi_history::durable::barrier_dir(self.root(), self.history.durability())?;
        }
        Ok(removed)
    }

    /// The old visible export of `host`, when it still holds exactly the
    /// bytes wi generated (a valid digest header); a hand-edited or foreign
    /// file there is left alone.
    fn legacy_export(&self, host: &str) -> Result<Option<(Target, String)>> {
        let (_, _, legacy) = host_export(host)?;
        if check_no_symlink(self.root(), legacy).is_err() {
            return Ok(None);
        }
        Ok(crate::contained::read_rel(self.root(), legacy)?
            .filter(|bytes| is_generated(bytes))
            .map(|bytes| {
                (
                    Target {
                        abs: self.root().join(legacy),
                        rel: legacy.to_owned(),
                    },
                    hash_bytes(&bytes),
                )
            }))
    }
}

fn host_export(host: &str) -> Result<(&'static str, &'static str, &'static str)> {
    HOST_EXPORTS
        .into_iter()
        .find(|(name, _, _)| *name == host)
        .ok_or_else(|| StoreError::Invalid("unknown export host".into()))
}

/// Whether `bytes` are an unmodified generated export: the header carries
/// the digest of everything after it.
fn is_generated(bytes: &[u8]) -> bool {
    std::str::from_utf8(bytes)
        .ok()
        .and_then(|text| text.split_once('\n'))
        .is_some_and(|(header, tail)| {
            header == format!("{GENERATED_PREFIX}{} -->", hash_bytes(tail.as_bytes()))
        })
}
